/* SPDX-License-Identifier: MIT
 * Small Linux-compatible seccomp classic-BPF interpreter.
 *
 * The implementation deliberately accepts only forward-only classic BPF and
 * the common seccomp-data loads generated by libseccomp/systemd. Filters are
 * immutable and inherited by reference across fork; each additional filter is
 * evaluated and the most restrictive action wins, as on Linux.
 */
#include <seccomp.h>
#include <process.h>
#include <heap.h>
#include <string.h>

#define BPF_CLASS(code) ((code) & 0x07u)
#define BPF_SIZE(code)  ((code) & 0x18u)
#define BPF_MODE(code)  ((code) & 0xe0u)
#define BPF_OP(code)    ((code) & 0xf0u)
#define BPF_SRC(code)   ((code) & 0x08u)

#define BPF_LD       0x00u
#define BPF_LDX      0x01u
#define BPF_ST       0x02u
#define BPF_STX      0x03u
#define BPF_ALU      0x04u
#define BPF_JMP      0x05u
#define BPF_RET      0x06u
#define BPF_MISC     0x07u
#define BPF_W        0x00u
#define BPF_IMM      0x00u
#define BPF_ABS      0x20u
#define BPF_MEM      0x60u
#define BPF_LEN      0x80u
#define BPF_ADD      0x00u
#define BPF_SUB      0x10u
#define BPF_MUL      0x20u
#define BPF_DIV      0x30u
#define BPF_OR       0x40u
#define BPF_AND      0x50u
#define BPF_LSH      0x60u
#define BPF_RSH      0x70u
#define BPF_NEG      0x80u
#define BPF_MOD      0x90u
#define BPF_XOR      0xa0u
#define BPF_JA       0x00u
#define BPF_JEQ      0x10u
#define BPF_JGT      0x20u
#define BPF_JGE      0x30u
#define BPF_JSET     0x40u
#define BPF_K        0x00u
#define BPF_X        0x08u
#define BPF_RVAL(code) ((code) & 0x18u)
#define BPF_A         0x10u
#define BPF_TAX      0x00u
#define BPF_TXA      0x80u

#define SECCOMP_RET_KILL_THREAD  0x00000000u
#define SECCOMP_RET_KILL_PROCESS 0x80000000u
#define SECCOMP_RET_TRAP         0x00030000u
#define SECCOMP_RET_ERRNO        0x00050000u
#define SECCOMP_RET_USER_NOTIF   0x7fc00000u
#define SECCOMP_RET_TRACE        0x7ff00000u
#define SECCOMP_RET_LOG          0x7ffc0000u
#define SECCOMP_RET_ALLOW        0x7fff0000u
#define SECCOMP_RET_ACTION       0xffff0000u
#define SECCOMP_RET_DATA         0x0000ffffu

#define SECCOMP_MAX_FILTER_INSNS 4096u
/* Linux caps the aggregate filter path at 32K instructions, not 16 filters.
 * systemd composes multiple policy filters when LockPersonality, namespaces,
 * and SystemCallFilter are enabled for one service. */
#define SECCOMP_MAX_FILTER_PATH_INSNS 32768u
#define SECCOMP_MAX_FILTER_CHAIN SECCOMP_MAX_FILTER_PATH_INSNS
#define AUDIT_ARCH_X86_64        0xc000003eu

struct seccomp_data_k {
    int32_t nr;
    uint32_t arch;
    uint64_t instruction_pointer;
    uint64_t args[6];
};

struct seccomp_filter {
    uint32_t refs;
    uint16_t count;
    struct seccomp_filter *previous;
    axon_bpf_insn_t instructions[];
};

static void seccomp_lock_process(const struct process *p)
{
    uint32_t *lock = (uint32_t *)&p->seccomp_lock;
    while (__atomic_exchange_n(lock, 1u, __ATOMIC_ACQUIRE))
        __asm__ volatile("pause" ::: "memory");
}

static void seccomp_unlock_process(const struct process *p)
{
    __atomic_store_n((uint32_t *)&p->seccomp_lock, 0u, __ATOMIC_RELEASE);
}

static int action_valid(uint32_t action) {
    switch (action & SECCOMP_RET_ACTION) {
    case SECCOMP_RET_KILL_THREAD:
    case SECCOMP_RET_KILL_PROCESS:
    case SECCOMP_RET_TRAP:
    case SECCOMP_RET_ERRNO:
    case SECCOMP_RET_TRACE:
    case SECCOMP_RET_LOG:
    case SECCOMP_RET_ALLOW:
        return 1;
    default:
        return 0;
    }
}

static int instruction_valid(const axon_bpf_insn_t *p, size_t pc, size_t count) {
    uint32_t code = p->code;
    uint32_t cls = BPF_CLASS(code);
    uint32_t op = BPF_OP(code);
    uint64_t target;

    switch (cls) {
    case BPF_LD:
    case BPF_LDX:
        if (BPF_SIZE(code) != BPF_W)
            return 0;
        switch (BPF_MODE(code)) {
        case BPF_IMM:
        case BPF_LEN:
            return 1;
        case BPF_MEM:
            return p->k < 16;
        case BPF_ABS:
            return cls == BPF_LD && p->k <= sizeof(struct seccomp_data_k) - 4;
        default:
            return 0;
        }
    case BPF_ST:
    case BPF_STX:
        return p->k < 16;
    case BPF_ALU:
        if (op == BPF_NEG)
            return BPF_SRC(code) == BPF_K;
        return op == BPF_ADD || op == BPF_SUB || op == BPF_MUL ||
               op == BPF_DIV || op == BPF_OR || op == BPF_AND ||
               op == BPF_LSH || op == BPF_RSH || op == BPF_MOD ||
               op == BPF_XOR;
    case BPF_JMP:
        if (op == BPF_JA) {
            target = (uint64_t)pc + 1 + p->k;
            return target < count;
        }
        if (op != BPF_JEQ && op != BPF_JGT && op != BPF_JGE && op != BPF_JSET)
            return 0;
        return (uint64_t)pc + 1 + p->jt < count &&
               (uint64_t)pc + 1 + p->jf < count;
    case BPF_RET:
        return BPF_RVAL(code) == BPF_K || BPF_RVAL(code) == BPF_A;
    case BPF_MISC:
        return code == (BPF_MISC | BPF_TAX) || code == (BPF_MISC | BPF_TXA);
    default:
        return 0;
    }
}

static int program_valid(const axon_bpf_insn_t *p, size_t count) {
    if (!p || count == 0 || count > SECCOMP_MAX_FILTER_INSNS)
        return 0;
    if (BPF_CLASS(p[count - 1].code) != BPF_RET)
        return 0;
    for (size_t i = 0; i < count; ++i) {
        if (!instruction_valid(&p[i], i, count))
            return 0;
        if (BPF_CLASS(p[i].code) == BPF_RET && BPF_RVAL(p[i].code) == BPF_K &&
            !action_valid(p[i].k))
            return 0;
        if (BPF_CLASS(p[i].code) == BPF_ALU &&
            (BPF_OP(p[i].code) == BPF_DIV || BPF_OP(p[i].code) == BPF_MOD) &&
            BPF_SRC(p[i].code) == BPF_K && p[i].k == 0)
            return 0;
    }
    return 1;
}

struct seccomp_filter *seccomp_filter_get(struct seccomp_filter *f) {
    if (f)
        __atomic_add_fetch(&f->refs, 1, __ATOMIC_ACQ_REL);
    return f;
}

void seccomp_filter_put(struct seccomp_filter *f) {
    while (f) {
        if (__atomic_sub_fetch(&f->refs, 1, __ATOMIC_ACQ_REL) != 0)
            return;
        struct seccomp_filter *prev = f->previous;
        kfree(f);
        f = prev;
    }
}

void seccomp_process_inherit(struct process *child, const struct process *parent) {
    if (!child || !parent)
        return;
    seccomp_lock_process(parent);
    child->no_new_privs = parent->no_new_privs;
    child->seccomp_mode = parent->seccomp_mode;
    child->seccomp_filters = seccomp_filter_get(parent->seccomp_filters);
    seccomp_unlock_process(parent);
}

void seccomp_process_release(struct process *p) {
    if (!p)
        return;
    seccomp_lock_process(p);
    struct seccomp_filter *old = p->seccomp_filters;
    p->seccomp_filters = NULL;
    p->seccomp_mode = 0;
    seccomp_unlock_process(p);
    seccomp_filter_put(old);
}

int seccomp_filter_install(struct process *p, const axon_bpf_insn_t *instructions,
                           size_t count) {
    if (!p || !program_valid(instructions, count))
        return -22; /* EINVAL */
    size_t bytes = sizeof(struct seccomp_filter) + count * sizeof(*instructions);
    struct seccomp_filter *f = (struct seccomp_filter *)kmalloc(bytes);
    if (!f)
        return -12; /* ENOMEM */
    f->refs = 1;
    f->count = (uint16_t)count;
    f->previous = NULL;
    memcpy(f->instructions, instructions, count * sizeof(*instructions));

    seccomp_lock_process(p);
    size_t chain = 0;
    size_t path_insns = count;
    int too_big = 0;
    for (struct seccomp_filter *it = p->seccomp_filters; it; it = it->previous) {
        chain++;
        if (path_insns > SECCOMP_MAX_FILTER_PATH_INSNS - it->count) {
            too_big = 1;
            break;
        }
        path_insns += it->count;
        if (chain > SECCOMP_MAX_FILTER_CHAIN) {
            too_big = 1;
            break;
        }
    }
    if (too_big || chain > SECCOMP_MAX_FILTER_CHAIN) {
        seccomp_unlock_process(p);
        seccomp_filter_put(f);
        return -7; /* E2BIG */
    }
    f->previous = seccomp_filter_get(p->seccomp_filters);
    struct seccomp_filter *old = p->seccomp_filters;
    p->seccomp_filters = f;
    p->seccomp_mode = 2;
    seccomp_unlock_process(p);
    seccomp_filter_put(old);
    return 0;
}

static uint32_t run_program(const struct seccomp_filter *f,
                            const struct seccomp_data_k *data) {
    uint32_t a = 0, x = 0, mem[16] = {0};
    size_t pc = 0;
    while (pc < f->count) {
        const axon_bpf_insn_t *i = &f->instructions[pc];
        uint32_t code = i->code;
        uint32_t cls = BPF_CLASS(code), op = BPF_OP(code);
        uint32_t rhs = BPF_SRC(code) == BPF_X ? x : i->k;
        switch (cls) {
        case BPF_LD:
            if (BPF_MODE(code) == BPF_IMM) a = i->k;
            else if (BPF_MODE(code) == BPF_LEN) a = sizeof(*data);
            else if (BPF_MODE(code) == BPF_MEM) a = mem[i->k];
            else memcpy(&a, (const uint8_t *)data + i->k, sizeof(a));
            break;
        case BPF_LDX:
            if (BPF_MODE(code) == BPF_IMM) x = i->k;
            else if (BPF_MODE(code) == BPF_LEN) x = sizeof(*data);
            else x = mem[i->k];
            break;
        case BPF_ST:
            mem[i->k] = a;
            break;
        case BPF_STX:
            mem[i->k] = x;
            break;
        case BPF_ALU:
            switch (op) {
            case BPF_ADD: a += rhs; break;
            case BPF_SUB: a -= rhs; break;
            case BPF_MUL: a *= rhs; break;
            case BPF_DIV: a = rhs ? a / rhs : 0; break;
            case BPF_OR: a |= rhs; break;
            case BPF_AND: a &= rhs; break;
            case BPF_LSH: a = rhs < 32 ? a << rhs : 0; break;
            case BPF_RSH: a = rhs < 32 ? a >> rhs : 0; break;
            case BPF_NEG: a = (uint32_t)(0u - a); break;
            case BPF_MOD: a = rhs ? a % rhs : 0; break;
            case BPF_XOR: a ^= rhs; break;
            default: return SECCOMP_RET_KILL_THREAD;
            }
            break;
        case BPF_JMP:
            if (op == BPF_JA) {
                pc += i->k;
                break;
            }
            if ((op == BPF_JEQ && a == rhs) ||
                (op == BPF_JGT && a > rhs) ||
                (op == BPF_JGE && a >= rhs) ||
                (op == BPF_JSET && (a & rhs)))
                pc += i->jt;
            else
                pc += i->jf;
            break;
        case BPF_RET:
            return (BPF_RVAL(code) == BPF_A) ? a : i->k;
        case BPF_MISC:
            if (code == (BPF_MISC | BPF_TAX)) x = a;
            else if (code == (BPF_MISC | BPF_TXA)) a = x;
            else return SECCOMP_RET_KILL_THREAD;
            break;
        default:
            return SECCOMP_RET_KILL_THREAD;
        }
        pc++;
    }
    return SECCOMP_RET_KILL_THREAD;
}

static int action_rank(uint32_t action) {
    switch (action & SECCOMP_RET_ACTION) {
    case SECCOMP_RET_KILL_PROCESS: return 9;
    case SECCOMP_RET_KILL_THREAD: return 8;
    case SECCOMP_RET_TRAP: return 7;
    case SECCOMP_RET_ERRNO: return 6;
    case SECCOMP_RET_USER_NOTIF: return 5;
    case SECCOMP_RET_TRACE: return 4;
    case SECCOMP_RET_LOG: return 2;
    case SECCOMP_RET_ALLOW: return 1;
    default: return 0;
    }
}

uint32_t seccomp_filter_evaluate(const struct process *p, uint32_t syscall_nr,
                                uint64_t ip, const uint64_t args[6]) {
    if (!p)
        return SECCOMP_RET_ALLOW;
    seccomp_lock_process(p);
    if (p->seccomp_mode == 0) {
        seccomp_unlock_process(p);
        return SECCOMP_RET_ALLOW;
    }
    if (p->seccomp_mode == 1) {
        seccomp_unlock_process(p);
        if (syscall_nr == 0 || syscall_nr == 1 || syscall_nr == 15 ||
            syscall_nr == 60 || syscall_nr == 231)
            return SECCOMP_RET_ALLOW;
        return SECCOMP_RET_KILL_THREAD;
    }
    struct seccomp_data_k data = {
        .nr = (int32_t)syscall_nr,
        .arch = AUDIT_ARCH_X86_64,
        .instruction_pointer = ip,
    };
    if (args)
        memcpy(data.args, args, sizeof(data.args));
    uint32_t best = SECCOMP_RET_ALLOW;
    for (const struct seccomp_filter *f = p->seccomp_filters; f; f = f->previous) {
        uint32_t action = run_program(f, &data);
        if (action_rank(action) == 0)
            action = SECCOMP_RET_KILL_THREAD;
        if (action_rank(action) > action_rank(best))
            best = action;
    }
    seccomp_unlock_process(p);
    return best;
}
